CREATE TABLE `salary_components` (`id` text PRIMARY KEY NOT NULL,`organization_id` text NOT NULL REFERENCES organizations(id) ON DELETE cascade,`name` text NOT NULL,`code` text NOT NULL,`component_type` text NOT NULL,`calculation_type` text DEFAULT 'fixed' NOT NULL,`default_value` real DEFAULT 0 NOT NULL,`is_taxable` integer DEFAULT false NOT NULL,`is_active` integer DEFAULT true NOT NULL,`created_at` integer DEFAULT (unixepoch()*1000) NOT NULL,`updated_at` integer DEFAULT (unixepoch()*1000) NOT NULL);
CREATE UNIQUE INDEX `salary_components_org_code_uq` ON `salary_components` (`organization_id`,`code`);
CREATE TABLE `staff_salary_assignments` (`id` text PRIMARY KEY NOT NULL,`organization_id` text NOT NULL REFERENCES organizations(id) ON DELETE cascade,`campus_id` text NOT NULL REFERENCES campuses(id) ON DELETE restrict,`staff_id` text NOT NULL REFERENCES staff(id) ON DELETE cascade,`base_salary` real NOT NULL,`effective_from` text NOT NULL,`effective_to` text,`payment_method` text DEFAULT 'bank_transfer' NOT NULL,`status` text DEFAULT 'active' NOT NULL,`notes` text,`created_by` text NOT NULL REFERENCES users(id),`created_at` integer DEFAULT (unixepoch()*1000) NOT NULL,`updated_at` integer DEFAULT (unixepoch()*1000) NOT NULL);
CREATE INDEX `staff_salary_assignment_staff_idx` ON `staff_salary_assignments` (`organization_id`,`staff_id`,`status`,`effective_from`);
CREATE UNIQUE INDEX `staff_salary_assignment_active_uq` ON `staff_salary_assignments` (`organization_id`,`staff_id`,`effective_from`);
CREATE TABLE `staff_salary_components` (`id` text PRIMARY KEY NOT NULL,`organization_id` text NOT NULL REFERENCES organizations(id) ON DELETE cascade,`salary_assignment_id` text NOT NULL REFERENCES staff_salary_assignments(id) ON DELETE cascade,`component_id` text NOT NULL REFERENCES salary_components(id) ON DELETE restrict,`value` real NOT NULL,`created_at` integer DEFAULT (unixepoch()*1000) NOT NULL,`updated_at` integer DEFAULT (unixepoch()*1000) NOT NULL);
CREATE UNIQUE INDEX `staff_salary_component_uq` ON `staff_salary_components` (`salary_assignment_id`,`component_id`);
CREATE TABLE `payroll_periods` (`id` text PRIMARY KEY NOT NULL,`organization_id` text NOT NULL REFERENCES organizations(id) ON DELETE cascade,`name` text NOT NULL,`period_month` text NOT NULL,`starts_on` text NOT NULL,`ends_on` text NOT NULL,`pay_date` text,`status` text DEFAULT 'draft' NOT NULL,`created_by` text NOT NULL REFERENCES users(id),`approved_by` text REFERENCES users(id),`approved_at` integer,`created_at` integer DEFAULT (unixepoch()*1000) NOT NULL,`updated_at` integer DEFAULT (unixepoch()*1000) NOT NULL);
CREATE UNIQUE INDEX `payroll_period_org_month_uq` ON `payroll_periods` (`organization_id`,`period_month`);
CREATE TABLE `payroll_items` (`id` text PRIMARY KEY NOT NULL,`organization_id` text NOT NULL REFERENCES organizations(id) ON DELETE cascade,`payroll_period_id` text NOT NULL REFERENCES payroll_periods(id) ON DELETE cascade,`campus_id` text NOT NULL REFERENCES campuses(id) ON DELETE restrict,`staff_id` text NOT NULL REFERENCES staff(id) ON DELETE cascade,`salary_assignment_id` text NOT NULL REFERENCES staff_salary_assignments(id) ON DELETE restrict,`base_salary` real NOT NULL,`earnings` real DEFAULT 0 NOT NULL,`deductions` real DEFAULT 0 NOT NULL,`absence_deduction` real DEFAULT 0 NOT NULL,`net_salary` real NOT NULL,`status` text DEFAULT 'draft' NOT NULL,`details_json` text DEFAULT '{}' NOT NULL,`created_at` integer DEFAULT (unixepoch()*1000) NOT NULL,`updated_at` integer DEFAULT (unixepoch()*1000) NOT NULL);
CREATE UNIQUE INDEX `payroll_item_period_staff_uq` ON `payroll_items` (`organization_id`,`payroll_period_id`,`staff_id`);
CREATE INDEX `payroll_item_campus_idx` ON `payroll_items` (`organization_id`,`campus_id`,`payroll_period_id`);
